'use strict';
// tools/cas-ccps/build-script-index.js (structure audit 4.7): the cas-ccps
// file index, generated from each script's PURPOSE: line and the project map.
// The committed index must match what the scripts produce, and the naming
// rule for generated files holds.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');
const cp = require('child_process');
const idx = require('../../tools/cas-ccps/build-script-index.js');

const BUILD = path.join(__dirname, '..', '..', 'tools', 'cas-ccps', 'build-script-index.js');

test('the committed SCRIPT_INDEX.md is current, and every script follows the header rules', () => {
  const r = cp.spawnSync(process.execPath, [BUILD, '--check'], { encoding: 'utf8' });
  assert.equal(r.status, 0, r.stderr + r.stdout);
});

test('--check fails on a stale or missing index, and --out writes what --check accepts', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'script-index-'));
  const stale = path.join(dir, 'stale.md');
  fs.writeFileSync(stale, 'old\n');
  assert.equal(cp.spawnSync(process.execPath, [BUILD, '--check', '--out', stale]).status, 1);
  assert.equal(cp.spawnSync(process.execPath, [BUILD, '--check', '--out', path.join(dir, 'none.md')]).status, 1);
  const out = path.join(dir, 'out.md');
  assert.equal(cp.spawnSync(process.execPath, [BUILD, '--out', out]).status, 0);
  assert.equal(cp.spawnSync(process.execPath, [BUILD, '--check', '--out', out]).status, 0);
});

test('purposeOf takes the first sentence, across lines, in either comment style', () => {
  assert.equal(idx.purposeOf('// PURPOSE: Moves rows. Then more.\n'), 'Moves rows.');
  assert.equal(idx.purposeOf('// PURPOSE: Moves rows into\n//          the queue. More.\n'), 'Moves rows into the queue.');
  assert.equal(idx.purposeOf('/**\n * PURPOSE: The unit rubrics, read by 53.\n */'), 'The unit rubrics, read by 53.');
  assert.equal(idx.purposeOf('// PURPOSE (plan L6, 2026-11-02): one doc per course.\n'), 'One doc per course.');
  assert.equal(idx.purposeOf('// PURPOSE: two lists\n//\n// USAGE: x\n'), 'Two lists');
  assert.equal(idx.purposeOf('// nothing here\n'), null);
  const long = idx.purposeOf('// PURPOSE: ' + 'word '.repeat(80) + 'end.\n');
  assert.ok(long.length <= 202 && long.endsWith(' …'), long);
  assert.equal(idx.purposeOf('// PURPOSE: a | b.\n'), 'A \\| b.', 'a pipe would break the table');
  assert.equal(idx.purposeOf('// PURPOSE: a \\| b.\n'), 'A \\\\\\| b.', 'a backslash is escaped too, so it cannot unescape a pipe');
});

test('generatorOf reads the GENERATED header, in either case', () => {
  assert.equal(idx.generatorOf('// GENERATED by tools/cas-ccps/x.js from'), 'tools/cas-ccps/x.js');
  assert.equal(idx.generatorOf(' * Generated by tools/cas-ccps/y.js, from'), 'tools/cas-ccps/y.js');
  assert.equal(idx.generatorOf('//   generated warm-up doc in the WarmUpRegistry'), null);
});

test('the index lists every script once, generated ones with their generator', () => {
  const { rows } = idx.collect();
  const files = fs.readdirSync(path.join(__dirname, '..', '..', 'cas-ccps', 'scripts')).filter((f) => f.endsWith('.js'));
  assert.deepEqual(rows.map((r) => r.file).sort(), files.sort());
  const gen = rows.filter((r) => r.generator).map((r) => r.file);
  assert.ok(gen.includes('79b_CanvasCartridgeData.js') && gen.includes('13c_StudentDashboardLessons.js'));
  assert.ok(!gen.includes('25_WarmUpWriter.js'), 'a header that mentions generated docs is not a generated file');
  rows.forEach((r) => {
    assert.ok(r.purpose, r.file + ' has no purpose');
    assert.ok(r.projects.length, r.file + ' is in no project');
  });
});
